// Check if the block to deallocate is the most recently allocated one
if (data + b.offset == p - b.size)
{
    // Reclaim the space by moving the stack pointer back
    p = data + b.offset;
}
// Clear the block's metadata (optional, but good practice)
b.offset = 0;
b.size = 0;
b.used = false;
else
{
    // If it's not the top block, mark it as free but don't reclaim space
    b.used = false;
}
return;
// END_CODE

